Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='idempotentrequests', at=datetime(2026, 10, 27, 0, 0, 0), actor='owner', title='A request is a content-addressed object, and its effect runs at most once', body="Every write is an object named by the hash of its content. Sending the same request twice is the same object, and its effect is memoised by that hash, so a retry never repeats an effect and independent effects can run in parallel. The box's acceptance, refusal and completion come back as receipt objects (docs/LOCALWRITES-PLAN-2026-11-01.md).", rationale='The owner: duplicates are idempotence; eventual consistency needs no waiting as long as applying an effect is idempotent.', supersedes=()))